import React, { useEffect, useState } from "react";
import api from "../services/api";
import ItemCard from "../components/ItemCard";
import "../styles/MyReports.css";

function MyReports() {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      setLoading(true);

      const response = await api.get("/items/my-items");

      if (response.data.success) {
        setReports(response.data.items);
      }
    } catch (error) {
      console.error(error);
      alert(error.response?.data?.message || "Failed to load reports.");
    } finally {
      setLoading(false);
    }
  };

  const deleteReport = async (id) => {
    try {
      const confirmDelete = window.confirm(
        "Are you sure you want to delete this report?"
      );

      if (!confirmDelete) return;

      const response = await api.delete(`/items/${id}`);

      if (response.data.success) {
        alert(response.data.message);

        // Refresh reports from database
        fetchReports();
      }
    } catch (error) {
      console.error(error);
      alert(error.response?.data?.message || "Delete failed.");
    }
  };

  if (loading) {
    return (
      <div className="reports-page">
        <h2 style={{ textAlign: "center" }}>Loading Reports...</h2>
      </div>
    );
  }

  return (
    <div className="reports-page">
      <h1>My Reports</h1>

      <p className="reports-subtitle">
        Manage your lost and found item reports
      </p>

      <div className="reports-grid">
        {reports.length > 0 ? (
          reports.map((item) => (
            <div className="report-box" key={item._id}>
              <ItemCard item={item} />

              <button
                className="delete-btn"
                onClick={() => deleteReport(item._id)}
              >
                Delete Report
              </button>
            </div>
          ))
        ) : (
          <h3>No Reports Available</h3>
        )}
      </div>
    </div>
  );
}

export default MyReports;
